    /** P129：按绑定点布局建根签名（`meshExtras != 0` 时追加 b8 段表 + t14/t15 顶点索引表）。*/
    fun D3D12CreateMeshRootSignature(bindings: MemorySegment?, count: Int, meshExtras: Int): Long {
        requireLoaded()
