            }
            val buf = scratch(0, total * 4L)
            val written = MH_surfacepresentmodes!!.invokeExact(buf, total) as Int
            val n = minOf(total, written.coerceAtLeast(0))
            val out = IntArray(n)
            for (i in 0 until n) {
                out[i] = buf.get(MCDRLayout.I32, i * 4L) as Int
            }
            return out
        } catch (t: Throwable) {
            throw unexpected(t)
        }
    }
