        }
        val arr = scratch(0, count * 8L)
        for (i in 0 until count) {
            arr.set(MCDRLayout.PTR, i * 8L, ptr(objects!![i]))
        }
        try {
            return ok(handle!!.invokeExact(ptr(ctx), arr, count) as Int)
        } catch (t: Throwable) {
            throw unexpected(t)
        }
    }
