    /**     * Register a completion callback: when the fence reaches `value` the monitor     * thread calls [D3D12FenceCallback.onFenceComplete]     * (`timeoutMs == 0` means no timeout).     *     * <p>The callback is invoked outside the registry lock, so it may register or unregister     * again. Each registration fires at most once; the handle is released after it fires.     * This is the project's only [Linker.upcallStub] — the JNI original     * needed a cached `JavaVM*`, a `NewGlobalRef`, per-invocation     * GetEnv/AttachCurrentThread bookkeeping and a `GetMethodID(cls, "onFenceComplete",     * "(JZ)V")` string lookup; all of that is now one integer handle into a registry.     */
    fun AsyncFenceRegisterCallback(mgr: Long, value: Long,
                                   callback: D3D12FenceCallback?, timeoutMs: Long): Boolean {
        requireLoaded()
        if (callback == null) {
            return false
        }
        val handle = NEXT_CALLBACK_HANDLE.getAndIncrement()
        CALLBACKS.put(handle, CallbackEntry(callback))
        try {
            val accepted = ok(MH_asyncfenceregistercallback!!.invokeExact(
                ptr(mgr), value, FENCE_STUB!!, handle.toLong(), timeoutMs) as Int)
            if (!accepted) {
                CALLBACKS.remove(handle)
            }
            return accepted
        } catch (t: Throwable) {
            CALLBACKS.remove(handle)
            throw unexpected(t)
        }
    }
    private val CALLBACKS = ConcurrentHashMap<Int, CallbackEntry>()
    private val NEXT_CALLBACK_HANDLE = AtomicInteger(1)
    private class CallbackEntry(val callback: D3D12FenceCallback) {
        val fired = AtomicBoolean()
    }
    /**     * Upcall target. Must never let an exception escape — the JVM terminates abruptly if an     * upcall stub's target throws — so everything is caught and reported to stderr.     */
    @JvmStatic
    private fun onFenceComplete(userHandle: Long, value: Long, completed: Int) {
        try {
            val handle = userHandle.toInt()
            val entry = CALLBACKS.get(handle) ?: return
            if (completed != 0 && !entry.fired.compareAndSet(false, true)) {
                return  // already fired for this registration
            }
            if (completed != 0) {
                CALLBACKS.remove(handle)
            }
            entry.callback.onFenceComplete(value, completed != 0)
        } catch (t: Throwable) {
            IllusionLogger.warnMessage("fence callback failed: ${t}")
        }
    }
    // ==================================================================
    // FFM linker bootstrap
    // ==================================================================
    private fun bindAll() {
        bindFenceStub()
        bindMetaAndDevice()
        bindCommand()
        bindPipelineSurfaceDraw()
        bindAsync()
        // P73: the native side no longer reads DX12_LOG_VERBOSE from the process environment
        // (see abi_meta.cpp mcdrSetLogVerbose) - the JVM side owns the switch and must push it.
        D3D12SetLogVerbose(LOG_VERBOSE)
        // P184：刚绑定时先按内置默认（恒定输出）初始化一次；真正的配置值由
        // IllusionLogger.applyFromConfig() 随后推过来。
        D3D12SetShutdownTraceAlways(true)
    }
